<?php
namespace App\Services;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Facades\Crypt;
use Illuminate\Support\Str;
use Illuminate\Validation\ValidationException;
class Store {
 public static function fail(string $message):never {throw ValidationException::withMessages(['store'=>$message]);}
 public function settings():array {$r=DB::table('shipping_rules')->whereNull('province')->first();return array_merge(DB::table('site_settings')->pluck('value','key')->all(),['shipping'=>(int)($r->amount??0),'free_above'=>$r?->free_above,'about'=>DB::table('site_settings')->where('key','about')->value('value')??'مارو؛ انتخاب‌های کوچک برای حال خوب.']);}
 public function catalog(bool $admin=false):array {return DB::table('products')->when(!$admin,fn($q)=>$q->where('status','published'))->orderByDesc('id')->get()->map(function($p)use($admin){$vs=DB::table('product_variants')->where('product_id',$p->id)->when(!$admin,fn($q)=>$q->where('published',true))->get()->map(function($v)use($admin){$v->price=(int)$v->price;$v->stock=$admin?(int)$v->stock:$this->available($v);$v->published=(bool)$v->published;return $v;})->all();$imgs=DB::table('product_images')->where('product_id',$p->id)->orderBy('position')->get()->map(fn($i)=>str_starts_with($i->path,'assets/')?$i->path:'/media/'.$i->id)->all();return array_merge((array)$p,['category'=>DB::table('categories')->where('id',$p->category_id)->value('name'),'variants'=>$vs,'images'=>$imgs,'image'=>$imgs[0]??'assets/sage.svg','featured'=>(bool)$p->featured,'demo'=>(bool)$p->demo]);})->filter(fn($p)=>$admin||count($p['variants']))->values()->all();}
 public function available(object $v):int {return max(0,$v->stock-(int)DB::table('inventory_reservations')->where('variant_id',$v->id)->where('status','active')->where('expires_at','>',now())->sum('quantity'));}
 public function quote(array $input,bool $lock=false):array {
  $items=collect($input['items'])->groupBy('variant_id')->map(fn($g)=>['variant_id'=>(int)$g[0]['variant_id'],'quantity'=>(int)$g->sum('quantity')])->sortBy('variant_id');$lines=[];$subtotal=0;
  foreach($items as $i){$v=DB::table('product_variants')->where('id',$i['variant_id'])->when($lock,fn($q)=>$q->lockForUpdate())->first();$p=$v?DB::table('products')->where('id',$v->product_id)->first():null;
   if(!$v||!$p||!$v->published||$p->status!=='published'||$i['quantity']<1||$i['quantity']>99||$this->available($v)<$i['quantity'])self::fail('موجودی یا وضعیت محصول تغییر کرده است؛ سبد را بررسی کنید.');
   if(config('maro.live')&&$p->demo)self::fail('محصول نمونه قابل خرید واقعی نیست.');
   $subtotal+=$v->price*$i['quantity'];$lines[]=['variant_id'=>$v->id,'name'=>$p->name,'variant_label'=>$v->color.' / '.$v->size,'sku'=>$v->sku,'quantity'=>$i['quantity'],'unit_price'=>$v->price];}
  $rule=DB::table('shipping_rules')->where('enabled',true)->where('province',$input['province']??'')->first()??DB::table('shipping_rules')->where('enabled',true)->whereNull('province')->first();if(!$rule)self::fail('قوانین ارسال هنوز تنظیم نشده است.');$shipping=$rule->free_above!==null&&$subtotal>=$rule->free_above?0:(int)$rule->amount;
  return ['subtotal'=>$subtotal,'shipping'=>$shipping,'total'=>$subtotal+$shipping,'lines'=>$lines];
 }
 public function signature(array $quote,string $owner):string {return hash_hmac('sha256',json_encode([$quote['lines'],$quote['shipping'],$owner]),config('app.key'));}
 public function start(array $input,string $owner):array {
  $result=DB::transaction(function()use($input,$owner){$existing=DB::table('orders')->where('idempotency_key',$input['idempotency_key'])->lockForUpdate()->first();if($existing){if(!hash_equals($existing->owner_hash,hash('sha256',$owner)))abort(403);return ['order'=>$existing,'existing'=>true];}
   $q=$this->quote($input,true);if(!hash_equals($this->signature($q,$owner),$input['quote_signature']??''))self::fail('قیمت یا ارسال تغییر کرده است. سفارش را دوباره بررسی کنید.');$token=bin2hex(random_bytes(32));$id=DB::table('orders')->insertGetId(array_merge(collect($input)->only(['name','mobile','province','city','address','postal','email','note'])->all(),['number'=>'MR-'.strtoupper(Str::random(12)),'token_hash'=>hash('sha256',$token),'token_encrypted'=>Crypt::encryptString($token),'owner_hash'=>hash('sha256',$owner),'idempotency_key'=>$input['idempotency_key'],'subtotal'=>$q['subtotal'],'shipping'=>$q['shipping'],'total'=>$q['total'],'created_at'=>now(),'updated_at'=>now()]));
   foreach($q['lines'] as $line){DB::table('order_items')->insert($line+['order_id'=>$id,'created_at'=>now(),'updated_at'=>now()]);DB::table('inventory_reservations')->insert(['order_id'=>$id,'variant_id'=>$line['variant_id'],'quantity'=>$line['quantity'],'expires_at'=>now()->addMinutes(config('maro.reservation_minutes')),'created_at'=>now(),'updated_at'=>now()]);}
   DB::table('payment_attempts')->insert(['order_id'=>$id,'gateway'=>config('maro.gateway'),'amount'=>$q['total'],'status'=>'requesting','created_at'=>now(),'updated_at'=>now()]);return ['order'=>DB::table('orders')->find($id),'existing'=>false];},5);
  $order=$result['order'];$token=Crypt::decryptString($order->token_encrypted);
  if($result['existing'])return ['token'=>$token,'message'=>'این سفارش قبلاً ثبت شده؛ وضعیت پرداخت را پیگیری کنید.'];
  $r=app(Gateway::class)->request($order);$status=$r['status'];DB::transaction(function()use($order,$r,$status){DB::table('orders')->where('id',$order->id)->lockForUpdate()->first();DB::table('payment_attempts')->where('order_id',$order->id)->update(['status'=>$status,'authority'=>$r['authority']??null,'updated_at'=>now()]);DB::table('orders')->where('id',$order->id)->update(['payment_status'=>in_array($status,['unknown','requesting'])?'review':($status==='pending'?'pending':$status),'updated_at'=>now()]);if(in_array($status,['failed','disabled']))DB::table('inventory_reservations')->where('order_id',$order->id)->update(['status'=>'released','updated_at'=>now()]);});
  return ['token'=>$token,'redirect'=>$r['redirect']??null,'message'=>match($status){'disabled'=>'درگاه غیرفعال است. هیچ پرداختی انجام نشده.','unknown'=>'در انتظار بررسی پرداخت؛ دوباره پرداخت نکنید.','failed'=>'درخواست پرداخت ناموفق بود.','pending'=>'سفارش ثبت شده؛ پرداخت هنوز تأیید نشده است.',default=>'در انتظار بررسی.'}];
 }
 public function retry(string $token):array {
  $order=DB::transaction(function()use($token){$o=DB::table('orders')->where('token_hash',hash('sha256',$token))->lockForUpdate()->first();if(!$o)abort(404);if(!in_array($o->payment_status,['failed','disabled']))self::fail('پرداخت قبلی نیازمند بررسی است یا تأیید شده؛ پرداخت مجدد مجاز نیست.');if(DB::table('payment_attempts')->where('order_id',$o->id)->whereIn('status',['unknown','pending','requesting','verified'])->exists())self::fail('ابتدا وضعیت تلاش قبلی باید مشخص شود.');
   foreach(DB::table('order_items')->where('order_id',$o->id)->orderBy('variant_id')->get()as $i){$v=DB::table('product_variants')->where('id',$i->variant_id)->lockForUpdate()->first();$p=DB::table('products')->find($v->product_id);if(!$v->published||$p->status!=='published'||$v->price!=$i->unit_price||$this->available($v)<$i->quantity||(config('maro.live')&&$p->demo))self::fail('قیمت یا موجودی تغییر کرده؛ سفارش جدید را بررسی کنید.');DB::table('inventory_reservations')->where('order_id',$o->id)->where('variant_id',$v->id)->update(['status'=>'active','expires_at'=>now()->addMinutes(config('maro.reservation_minutes')),'updated_at'=>now()]);}
   DB::table('orders')->where('id',$o->id)->update(['payment_status'=>'pending','updated_at'=>now()]);DB::table('payment_attempts')->insert(['order_id'=>$o->id,'gateway'=>config('maro.gateway'),'amount'=>$o->total,'status'=>'requesting','created_at'=>now(),'updated_at'=>now()]);return $o;},5);
  $result=app(Gateway::class)->request($order);$status=$result['status'];DB::transaction(function()use($order,$result,$status){DB::table('orders')->where('id',$order->id)->lockForUpdate()->first();$a=DB::table('payment_attempts')->where('order_id',$order->id)->latest('id')->first();DB::table('payment_attempts')->where('id',$a->id)->update(['status'=>$status,'authority'=>$result['authority']??null,'updated_at'=>now()]);DB::table('orders')->where('id',$order->id)->update(['payment_status'=>$status==='unknown'?'review':$status,'updated_at'=>now()]);if(in_array($status,['disabled','failed']))DB::table('inventory_reservations')->where('order_id',$order->id)->update(['status'=>'released','updated_at'=>now()]);});return ['redirect'=>$result['redirect']??null,'message'=>$status==='unknown'?'در انتظار بررسی؛ دوباره پرداخت نکنید.':($status==='disabled'?'درگاه غیرفعال است.':'وضعیت پرداخت: '.$status)];
 }
 public function reconcile(int $attemptId):string {$a=DB::table('payment_attempts')->find($attemptId);if(!$a)abort(404);if($a->status==='verified')return DB::table('orders')->where('id',$a->order_id)->value('payment_status')==='paid_exception'?'paid_exception':'verified';return $this->settle($attemptId,app(Gateway::class)->verify($a));}
 public function settle(int $attemptId,array $result):string {
  return DB::transaction(function()use($attemptId,$result){$initial=DB::table('payment_attempts')->find($attemptId);if(!$initial)abort(404);$o=DB::table('orders')->where('id',$initial->order_id)->lockForUpdate()->first();$a=DB::table('payment_attempts')->where('id',$attemptId)->lockForUpdate()->first();if($a->status==='verified')return $o->payment_status==='paid_exception'?'paid_exception':'verified';
   $status=$result['status']??'unknown';if($status==='verified'&&(($result['amount']??null)!==$o->total||($result['amount']??null)!==$a->amount||($result['authority']??null)!==$a->authority||empty($result['reference'])))$status='unknown';
   if($status!=='verified'){DB::table('payment_attempts')->where('id',$a->id)->update(['status'=>$status,'checks'=>$a->checks+1,'last_checked_at'=>now(),'updated_at'=>now()]);DB::table('orders')->where('id',$o->id)->whereNotIn('payment_status',['paid','paid_exception'])->update(['payment_status'=>$status==='failed'?'failed':'review','updated_at'=>now()]);if($status==='failed')DB::table('inventory_reservations')->where('order_id',$o->id)->where('status','active')->update(['status'=>'released','updated_at'=>now()]);return $status;}
   $reservations=DB::table('inventory_reservations')->where('order_id',$o->id)->orderBy('variant_id')->get();$locked=[];$can=true;
   foreach($reservations as $r){$v=DB::table('product_variants')->where('id',$r->variant_id)->lockForUpdate()->first();$other=DB::table('inventory_reservations')->where('variant_id',$v->id)->where('order_id','!=',$o->id)->where('status','active')->where('expires_at','>',now())->sum('quantity');if($v->stock-$other<$r->quantity)$can=false;$locked[]=$r;}
   DB::table('payment_attempts')->where('id',$a->id)->update(['status'=>'verified','reference'=>$result['reference'],'last_checked_at'=>now(),'updated_at'=>now()]);
   if(in_array($o->payment_status,['paid','paid_exception'])){DB::table('orders')->where('id',$o->id)->update(['payment_status'=>'paid_exception','exception_reason'=>'multiple_verified_attempts','updated_at'=>now()]);return 'paid_exception';}
   if(!$can){DB::table('orders')->where('id',$o->id)->update(['payment_status'=>'paid_exception','exception_reason'=>'late_payment_insufficient_stock','updated_at'=>now()]);DB::table('inventory_reservations')->where('order_id',$o->id)->update(['status'=>'released','updated_at'=>now()]);return 'paid_exception';}
   foreach($locked as $r){DB::table('product_variants')->where('id',$r->variant_id)->update(['stock'=>DB::raw('stock - '.(int)$r->quantity),'revision'=>DB::raw('revision + 1'),'updated_at'=>now()]);DB::table('stock_movements')->insert(['variant_id'=>$r->variant_id,'order_id'=>$o->id,'quantity'=>-$r->quantity,'event_key'=>'sale:'.$o->id.':'.$r->variant_id,'reason'=>'verified_payment','created_at'=>now(),'updated_at'=>now()]);}
   DB::table('inventory_reservations')->where('order_id',$o->id)->update(['status'=>'consumed','updated_at'=>now()]);DB::table('orders')->where('id',$o->id)->update(['payment_status'=>'paid','fulfillment_status'=>'processing','updated_at'=>now()]);return 'verified';
  },5);
 }
 public function expire():int {return DB::table('inventory_reservations')->where('status','active')->where('expires_at','<=',now())->update(['status'=>'expired','updated_at'=>now()]);}
}
